-- zz_111_beispielfaelle.sql
-- ERZEUGT aus services/api/app/services/demo_inhalt.py - nicht von Hand bearbeiten.
-- Neu erzeugen: cd services/api && .venv/Scripts/python.exe -m app.services.demo_migration
--
-- WARUM
-- Die Beispielfaelle Lena und Marco sind das Erste, was jede Fachperson sieht. Die alten
-- Seeds (18, 27) bestanden aus zwanzig gleich langen, gleich gebauten Szenen mit Mustern
-- ausserhalb der Klassenliste, und Lenas und Marcos Fassung desselben Geburtstags passten
-- nicht zusammen. Jetzt: 25 und 15 Szenen von einer Zeile bis zu einer halben Seite, dieselben
-- Abende aus zwei Sichten, Belege auch gegen die naheliegende Deutung.
--
-- WAS PASSIERT
-- 1) Anliegen und Fragebogen beider Faelle neu (Belastung jetzt auf der 1-10-Skala der App)
-- 2) Szenen ersetzt - feste Ids, feste Nummern, auf die Fall-FAQ und Bericht zeigen
-- 3) Skalen, Themen und Hypothesen neu
-- 4) Demo-Notizen und -Bericht der Fachpersonen nachgezogen, aber NUR unbearbeitete
--    (updated_at = created_at, angelegt zusammen mit der Demo-Freigabe). Was eine
--    Fachperson geaendert hat, bleibt stehen - auch wenn die Szenennummern dann alt sind.
-- 5) Fall-FAQ: vorhandene Laeufe an Demo-Freigaben geloescht und faq_enabled gesetzt.
--    Die API legt die Laeufe beim naechsten Laden neu an (demo_service), und zwar erst,
--    wenn die Szenen hier eingespielt sind.
--
-- Angefasst werden nur die beiden festen Beispiel-Fall-Ids und Demo-Freigaben.
-- Idempotent, in einer Transaktion.
--
-- Prod (VOR dem API-Rebuild):
--   docker compose -f docker-compose.prod.yml exec -T postgres psql -v ON_ERROR_STOP=1 -U echob -d echob < infra/docker/postgres/init/zz_111_beispielfaelle.sql

BEGIN;

-- ── 1) Anliegen und Fragebogen ───────────────────────────────────────────────

UPDATE cases SET main_concern = 'Nach der Trennung verstehen, was in diesen zweieinhalb Jahren passiert ist, und wieder meiner eigenen Wahrnehmung trauen.' WHERE id = 'dec01000-0000-4000-a000-0000000000ca';
VALUES ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'Zweieinhalb Jahre mit Marco, davon zwei Jahre in seiner Wohnung. Am Anfang überwältigend, er hat mich auf Händen getragen. Später immer öfter abwertend und kontrollierend, dazwischen Phasen, in denen er wunderbar war. Seit vier Monaten getrennt, über das gemeinsame Konto und den Freundeskreis noch in Kontakt.', 'Wenn ich etwas Eigenes mache, mit Freundinnen, bei der Arbeit, an meinem Geburtstag, kommt eine Spitze oder er redet tagelang nicht mit mir. Am Ende entschuldige ich mich, und über das Eigentliche wird nie gesprochen.', 'Ich traue meiner eigenen Wahrnehmung nicht mehr und brauche Beweise, um mir selbst zu glauben. Dazu der Kontaktverlust zu Freundinnen und der Schlaf.', 'Mein Geburtstag. Er hat meinen Freundinnen hinter meinem Rücken geschrieben, ich sei krank, damit wir in sein Hotel fahren. Als ich es angesprochen habe, hat er zwei Wochen nicht mit mir geredet, und danach kam ein Wochenende an der Ostsee, als wäre nichts gewesen.', 'Die Nachrichten jeden Morgen um sechs am Anfang. Heiligabend auf der Treppe vor der verschlossenen Tür. Und die drei Tage, als mein Vater im Krankenhaus lag. Da war er wunderbar, und das macht es so schwer.', 8, 'elevated', 'Marco', '[{"label": "Schuldumkehr nach Konflikten", "confidence": "high", "source": "onboarding"}, {"label": "Wechsel von Idealisierung und Abwertung", "confidence": "high", "source": "onboarding"}, {"label": "Kontrolle über Geld und Kontakte", "confidence": "medium", "source": "onboarding"}]'::jsonb)
ON CONFLICT (case_id) DO UPDATE SET relationship_description = EXCLUDED.relationship_description, typical_scenes = EXCLUDED.typical_scenes, main_burden = EXCLUDED.main_burden, significant_event = EXCLUDED.significant_event, memorable_scenes = EXCLUDED.memorable_scenes, distress_score = EXCLUDED.distress_score, safety_status = EXCLUDED.safety_status, person_name = EXCLUDED.person_name, pattern_hypotheses = EXCLUDED.pattern_hypotheses, updated_at = NOW();

UPDATE cases SET main_concern = 'Verstehen, warum aus so viel Nähe ständige Kritik wurde, und warum ich am Ende als der Schuldige dastehe.' WHERE id = 'dec01000-0000-4000-a000-0000000000cb';
VALUES ('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'Zweieinhalb Jahre mit Lena, zwei davon in meiner Wohnung. Der Anfang war das Beste, was mir je passiert ist. Dann hatte ich immer öfter das Gefühl, nie gut genug zu sein und mich für alles rechtfertigen zu müssen. Seit der Trennung erzählt sie eine Geschichte über mich, in der ich mich nicht wiedererkenne.', 'Ich plane etwas für uns, und ihr sind ihre Leute wichtiger. Wenn ich mich dann zurückziehe, um nicht laut zu werden, heißt es, ich würde sie bestrafen.', 'Das Gefühl, der Böse zu sein, obwohl ich mir solche Mühe gegeben habe. Und dass sie gegangen ist, genau wie sie es angekündigt hat.', 'Ihr Geburtstag. Ich hatte wochenlang ein Hotel geplant, und ihr war ein Abend mit ihren Freundinnen wichtiger. Seitdem ging es immer um meine Fehler.', 'Die drei Tage im Krankenhaus bei ihrem Vater. Der Abend, an dem sie gesagt hat, dass sie geht, wenn es so weitergeht. Und dass ihre Schwester am Ende unten im Auto gewartet hat.', 6, 'none', 'Lena', '[{"label": "Gefühl ständiger Kritik", "confidence": "high", "source": "onboarding"}, {"label": "Rückzug bei Überforderung", "confidence": "medium", "source": "onboarding"}, {"label": "Angst, verlassen zu werden", "confidence": "medium", "source": "onboarding"}]'::jsonb)
ON CONFLICT (case_id) DO UPDATE SET relationship_description = EXCLUDED.relationship_description, typical_scenes = EXCLUDED.typical_scenes, main_burden = EXCLUDED.main_burden, significant_event = EXCLUDED.significant_event, memorable_scenes = EXCLUDED.memorable_scenes, distress_score = EXCLUDED.distress_score, safety_status = EXCLUDED.safety_status, person_name = EXCLUDED.person_name, pattern_hypotheses = EXCLUDED.pattern_hypotheses, updated_at = NOW();

-- ── 2) Szenen ────────────────────────────────────────────────────────────────

DELETE FROM scenes WHERE case_id IN ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-0000000000cb');



-- ── 3) Skalen, Themen, Hypothesen ────────────────────────────────────────────

DELETE FROM scale_scores WHERE case_id IN ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-0000000000cb');
DELETE FROM topic_summaries WHERE case_id IN ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-0000000000cb');
DELETE FROM case_hypotheses WHERE case_id IN ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-0000000000cb');



-- ── 4) Unbearbeitete Demo-Notizen und -Berichte nachziehen ───────────────────
-- updated_at bleibt, wie es ist: Das hier ist keine Bearbeitung durch die Fachperson,
-- und eine spaetere Fassung der Beispielfaelle soll dieselben Zeilen wiederfinden.

UPDATE professional_session_notes n SET content = '{"sections": [{"heading": "Anliegen", "text": "Lena kommt nach der Trennung von Marco (zweieinhalb Jahre Beziehung). Sie möchte verstehen, was passiert ist, und wieder ihrer eigenen Wahrnehmung trauen. Hoher Leidensdruck (Fragebogen 8/10), ausgeprägte Selbstzweifel."}, {"heading": "Beobachtungen", "text": "Schildert einen überwältigenden Beginn, danach Abwertung, Schweigen als Antwort auf Kritik und Schuldumkehr (Szenen 2, 6, 7, 14). Reflektiert und genau: hält auch entlastende Szenen fest (Szene 9) und benennt eigene Anteile offen (Szene 15). Stellt die eigene Wahrnehmung schnell infrage."}, {"heading": "Erste Einschätzung", "text": "Bild einer länger andauernden, emotional belastenden Beziehungsdynamik mit Kontrolle über Geld, Handy und Kontakte. Sicherheitsrelevant: Drohung und kurz versperrte Tür beim Auszug (Szene 20); derzeit kein Hinweis auf akute Gefährdung. Stabilisierung und Psychoedukation vor jeder Konfrontation. Keine Diagnose."}, {"heading": "Vereinbarungen", "text": "- Wöchentliche Termine vorerst\n- Szenen weiter festhalten, auch kurze\n- Kontakt zu Marco auf das Nötigste begrenzen (Kontoauflösung)"}]}'::jsonb
  FROM case_shares s
 WHERE s.is_demo AND s.case_id = 'dec01000-0000-4000-a000-0000000000ca'
   AND n.case_id = s.case_id AND n.professional_user_id = s.professional_user_id
   AND n.title = 'Erstgespräch'
   AND n.updated_at = n.created_at
   AND n.created_at BETWEEN s.created_at AND s.created_at + interval '1 minute';

UPDATE professional_session_notes n SET content = '{"sections": [{"heading": "Thema", "text": "Umgang mit dem Sog nach kurzen, kühlen Nachrichten von Marco; die eigene Wahrnehmung stärken."}, {"heading": "Verlauf", "text": "Lena berichtet von einem unbeschwerten Tag mit ihrer besten Freundin (Szene 24) und von zwei Tagen Grübeln nach einer einzigen Nachricht (Szene 25). Erkennt den Ablauf zunehmend selbst und ist stolz auf ihre kurze Antwort."}, {"heading": "Intervention", "text": "Psychoedukation zum Wechsel von Zuwendung und Entzug (Szenen 8, 9, 16) und zu Schuldumkehr; Realitätsanker: Was habe ich erlebt, was wurde daraus gemacht (Szene 3); Ressourcenarbeit mit Schwester und Freundin."}, {"heading": "Nächste Schritte", "text": "- Vorlage für kurze, sachliche Antworten zur Kontoauflösung (Szene 23)\n- Frühwarnzeichen des Grübelns benennen\n- Schlaf beobachten (Szenen 7, 12)"}]}'::jsonb
  FROM case_shares s
 WHERE s.is_demo AND s.case_id = 'dec01000-0000-4000-a000-0000000000ca'
   AND n.case_id = s.case_id AND n.professional_user_id = s.professional_user_id
   AND n.title = 'Sitzung 2 — Stabilisierung'
   AND n.updated_at = n.created_at
   AND n.created_at BETWEEN s.created_at AND s.created_at + interval '1 minute';

UPDATE professional_reports n SET content = '{"sections": [{"heading": "Ausgangslage und Kontext", "text": "Ende 30, nach zweieinhalb Jahren Beziehung von Marco getrennt; über das gemeinsame Konto weiter in Kontakt. Beruflich stabil. Hauptbelastung: Zweifel an der eigenen Wahrnehmung, Schlafprobleme, Rückzug gemeinsamer Freunde (Szene 22)."}, {"heading": "Wiederkehrende Muster und Dynamiken", "text": "Wiederkehrender Ablauf: Eigenständigkeit Lenas (Szenen 4, 6, 17) → Spitze oder Schweigen (Szenen 7, 17) → Entschuldigung Lenas oder große Geste ohne Klärung (Szenen 6, 8, 18). Ihre Wahrnehmung wird wiederholt für falsch erklärt (Szenen 3, 10, 12). Kontrolle über Geld, Handy und Kontakte (Szenen 5, 6, 11). Nach ihrer Trennungsdrohung (Szene 15) eine mehrmonatige ruhige Phase (Szene 16)."}, {"heading": "Arbeitshypothesen", "text": "Ängstliche Bindungsanteile verstärken den Sog des Wechsels von Zuwendung und Entzug (Szenen 7, 16). Kumulative Belastung mit Hypervigilanz (Szene 13) und Schlafstörung (Szenen 7, 12). Tastend, überprüfbar."}, {"heading": "Störungsbezogene Einschätzung", "text": "Im Fremdbericht mehrere narzisstisch anmutende Anhaltspunkte bei Marco: Kränkbarkeit bei Eigenständigkeit, Herabsetzung vor Dritten, Schuldumkehr (Szenen 12, 14, 17). Deutliche Gegenhinweise: verlässliche Fürsorge in der Krise (Szene 9), monatelange Zuwendung (Szene 16), angekündigte Therapie (Szene 21). Ausschließlich einseitige Schilderung, keine direkte Exploration möglich. Ausdrücklich Arbeitshypothese, keine Diagnose."}, {"heading": "Ressourcen und Schutzfaktoren", "text": "Hohe Reflexionsfähigkeit (Szenen 9, 15), tragfähige Beziehung zur Schwester (Szenen 19, 20), wiederhergestellte Freundschaft (Szene 24), Handlungsfähigkeit unter Druck (Szenen 20, 23, 25)."}, {"heading": "Nächste Schritte", "text": "- Stabilisierung und Psychoedukation vor Konfrontation\n- Kontaktmanagement rund um die Kontoauflösung\n- Drohung und versperrte Tür beim Auszug nachgehen (Szene 20)\n- Verlauf der Belastung weiter dokumentieren"}], "disclaimer": "Dieser Bericht ist eine KI-gestützte fachliche Einschätzung auf Basis des freigegebenen Materials und der Notizen, Hypothesen und Zusammenfassungen der Fachperson. Er kann wahrscheinlichkeits- und merkmalsbasierte Überlegungen zu Störungsbildern enthalten, stellt jedoch keine klinische Diagnose dar, ist fachlich zu validieren und nicht zur Weitergabe als Diagnose an die Klient:in bestimmt."}'::jsonb
  FROM case_shares s
 WHERE s.is_demo AND s.case_id = 'dec01000-0000-4000-a000-0000000000ca'
   AND n.case_id = s.case_id AND n.professional_user_id = s.professional_user_id
   AND n.source = 'standard:standort' AND n.title = 'Fall-Standortbestimmung (Beispiel)'
   AND n.updated_at = n.created_at
   AND n.created_at BETWEEN s.created_at AND s.created_at + interval '1 minute';

-- ── 5) Fall-FAQ an den Demo-Freigaben ────────────────────────────────────────

DELETE FROM case_faq_runs r USING case_shares s
 WHERE r.share_id = s.id AND s.is_demo AND s.case_id IN ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-0000000000cb');
UPDATE case_shares SET faq_enabled = true
 WHERE is_demo AND NOT faq_enabled AND case_id IN ('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-0000000000cb');

COMMIT;
