INSERT INTO onboarding_answers (case_id, user_id, relationship_description, typical_scenes, main_burden, significant_event, memorable_scenes, distress_score, safety_status, person_name, pattern_hypotheses)
INSERT INTO onboarding_answers (case_id, user_id, relationship_description, typical_scenes, main_burden, significant_event, memorable_scenes, distress_score, safety_status, person_name, pattern_hypotheses)
INSERT INTO scenes (id, case_id, user_id, scene_no, title, scene_date, description, user_reaction, distress_score, safety_level, pattern_tags, confirmed_by_user, input_mode, created_at, updated_at) VALUES
('dec0a000-0000-4000-a000-000000000001', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 1, 'Jeden Morgen um sechs eine Nachricht', '2023-09-16', E'Kennengelernt haben wir uns Ende August auf Miras Geburtstag, im Garten ihrer Eltern. Er hat den ganzen Abend nur mit mir geredet. Am nächsten Morgen um sechs kam die erste Nachricht: „Bist du schon wach? Ich seit vier. Wegen dir.“\n\nSeitdem jeden Morgen um sechs. Manchmal ein Foto vom Sonnenaufgang, manchmal nur ein Satz. Nach drei Wochen hat er gesagt, er habe noch nie jemanden getroffen, der ihn so versteht, wir seien Seelenverwandte. Letzte Woche hat er mir Wohnungsanzeigen geschickt, halb im Spaß. Heute hat er gefragt, ob ich Weihnachten seine Mutter kennenlernen will.\n\nIch habe Ja gesagt. Es ist schön. Es ist nur alles so schnell, und wenn ich das Mira gegenüber sage, klinge ich undankbar.', 'Verliebt wie mit zwanzig. Und ein bisschen außer Atem, als würde ich hinterherlaufen, obwohl es doch um mich geht.', 1, 'none', '["Idealisierung"]'::jsonb, true, 'freetext', '2023-09-16 19:00:00+00', '2023-09-16 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000002', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 2, 'Peinlich naiv', '2023-11-04', E'Abendessen mit meinem Team, zum ersten Mal mit Marco. Ich habe von dem Projekt in Leipzig erzählt, auf das ich wirklich stolz bin. Er hat mich zweimal verbessert, einmal bei einer Zahl, einmal bei der Reihenfolge, beide Male freundlich lachend.\n\nIm Auto hat er erst nichts gesagt. An der Ampel dann: „Das war peinlich naiv, wie du das erzählt hast. Die haben doch gemerkt, dass du nicht weißt, wovon du redest.“\n\nIch habe mich entschuldigt. Wofür genau, wusste ich nicht.', 'Beschämt. Ich habe die halbe Nacht jedes Gespräch im Kopf nachgespielt und die Stelle gesucht, an der ich mich blamiert habe. Ich habe keine gefunden.', 3, 'none', '["Abwertung", "Anpassung"]'::jsonb, true, 'guided', '2023-11-04 19:00:00+00', '2023-11-04 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000003', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 3, 'Die Nachricht, die es beweist', '2023-12-10', E'Gestern war Papas Siebzigster. Marco hatte vor Wochen zugesagt mitzukommen. Am Freitagabend hat er gesagt, davon sei nie die Rede gewesen, das Wochenende sei längst verplant. „Du denkst dir Sachen aus, Lena. Das machst du öfter.“\n\nIch bin allein gefahren. Meine Mutter hat dreimal gefragt, wo er ist.\n\nNachts im Gästezimmer habe ich angefangen, im Handy zurückzuscrollen, weil ich mir selbst nicht mehr sicher war. Um halb zwei habe ich sie gefunden, vom 2. November: „Klar komme ich mit, ich freu mich auf deinen Vater!“\n\nHeute habe ich ihm den Screenshot gezeigt. Er hat kurz draufgesehen und gesagt: „Dann habe ich mich missverständlich ausgedrückt. Können wir jetzt bitte über was anderes reden?“', 'Erleichtert, dass es die Nachricht gibt. Und erschrocken darüber, dass ich eine Nachricht brauchte, um mir selbst zu glauben.', 4, 'none', '["Wahrnehmungsverunsicherung", "Rechtfertigung/Abwehr", "Wortbruch"]'::jsonb, true, 'guided', '2023-12-10 19:00:00+00', '2023-12-10 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000004', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 4, 'Mira nicht erwähnt', '2024-01-18', 'Heute mit Mira im Kino. Marco habe ich gesagt, ich sei länger im Büro. Seit er sagt, dass sie mich runterzieht, ist es so einfach leichter.', 'Schlechtes Gewissen, als hätte ich etwas Verbotenes getan. Dabei war es nur Kino.', 2, 'none', '["Isolation", "Anpassung"]'::jsonb, true, 'freetext', '2024-01-18 19:00:00+00', '2024-01-18 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000005', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 5, 'Wofür brauchst du den?', '2024-03-02', E'Seit Februar wohne ich bei Marco. Das gemeinsame Konto war seine Idee, „der Einfachheit halber“. Alle Fixkosten laufen darüber, und ich zahle mehr ein, weil ich mehr verdiene.\n\nHeute kam ich mit einem Mantel nach Hause, 280 Euro im Schlussverkauf. Er hatte die Abbuchung schon in der App gesehen, bevor ich die Tüte abgestellt hatte. „Wofür brauchst du den? Du hast doch einen.“ Dann wollte er den Kassenbon sehen.\n\nVor zwei Wochen hat er sich ein Rennrad für 2.400 Euro gekauft, vom gemeinsamen Konto. Darüber haben wir nicht gesprochen. Ich habe es an der Abbuchung gesehen.', 'Ich habe den Bon gesucht und mich dabei gefühlt wie mit vierzehn. Ich verdiene mehr als er und muss mich trotzdem erklären.', 3, 'none', '["Kontrolle"]'::jsonb, true, 'guided', '2024-03-02 19:00:00+00', '2024-03-02 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000006', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 6, 'Mein Geburtstag', '2024-04-12', E'Für heute Abend hatte ich beim Italiener an der Ecke einen Tisch für acht reserviert: Mira, Katrin, zwei Kolleginnen, ihre Männer, Marco und ich. Seit Wochen geplant, Marco wusste davon.\n\nBeim Frühstück hat er mir einen Umschlag gegeben: eine Nacht in einem Wellnesshotel an der Seenplatte, heute, Abfahrt um vier. Ich habe mich gefreut und gefragt, ob wir morgen fahren können, heute sei doch der Italiener. Er hat den Umschlag wieder eingesteckt.\n\nUm halb drei schrieb Mira: „Oh nein, gute Besserung, Süße! Wir holen das nach 💐“. In der Gruppe, in die ich Marco zum Planen aufgenommen hatte, stand von ihm, 13:12 Uhr: „Lena hat sich was eingefangen, wir müssen heute leider absagen.“\n\nIch habe ihn gefragt, was das soll. Er hat gesagt, er habe wochenlang etwas Besonderes geplant und ich hätte es ihm vor die Füße geworfen. „Ich wollte dich überraschen, und du bist einfach nur undankbar.“ Irgendwann hat er geweint.\n\nDen Freundinnen habe ich nicht geschrieben, dass es nicht stimmt. Ich wusste nicht, wie, ohne ihn bloßzustellen. Katrin hat angerufen und gefragt, ob sie mir Suppe vorbeibringen soll. Ich habe gesagt, es gehe schon. Um vier sind wir gefahren.\n\nIm Hotel war er zärtlich, hat Champagner bestellt und gesagt, dass er sich keinen besseren Menschen vorstellen kann. Ich lag nachts wach und habe mich gefragt, ob ich wirklich undankbar bin.', 'Wut, und sofort danach der Zweifel, ob ich überreagiere. Am nächsten Morgen habe ich mich für den Streit entschuldigt.', 4, 'none', '["Schuldumkehr", "Isolation", "Anpassung"]'::jsonb, true, 'freetext', '2024-04-12 19:00:00+00', '2024-04-12 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000007', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 7, 'Tag neun', '2024-04-23', 'Tag neun, seit ich gesagt habe, dass es nicht in Ordnung war, meinen Freundinnen zu schreiben, ich sei krank. Er sagt dem Kater Guten Morgen, mir nicht. Heute habe ich zum dritten Mal gefragt, ob wir reden können. Er hat den Fernseher lauter gemacht.', 'Ich schlafe kaum. Ich würde fast alles tun, damit es aufhört.', 5, 'none', '["Schweigen/Rückzug"]'::jsonb, true, 'freetext', '2024-04-23 19:00:00+00', '2024-04-23 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000008', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 8, 'Das Wochenende an der Ostsee', '2024-04-28', E'Am Freitag, Tag vierzehn, stand er mit einem riesigen Strauß Ranunkeln in der Küche, meinen Lieblingsblumen. Er hat geweint und gesagt, er sei ein Idiot, er könne ohne mich nicht leben, ich sei das Beste, was ihm je passiert ist. Die Taschen waren schon gepackt: zwei Nächte Warnemünde.\n\nEs war wunderschön. Wir sind stundenlang am Strand gelaufen, er hat meine Hand nicht losgelassen. Am Samstagabend habe ich vorsichtig angefangen, über den Geburtstag und die zwei Wochen zu reden. Er hat mich geküsst und gesagt: „Lass uns das Wochenende nicht kaputtmachen.“\n\nWir haben nie wieder darüber gesprochen. Mira und die anderen glauben bis heute, ich war an meinem Geburtstag krank.', 'Erleichterung, so groß, dass sie wehtat. Und ganz leise: schon wieder.', 3, 'none', '["Reparatur bleibt aus", "Idealisierung"]'::jsonb, true, 'guided', '2024-04-28 19:00:00+00', '2024-04-28 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000009', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 9, 'Als Papa im Krankenhaus lag', '2024-06-01', E'Samstagnacht um zwei hat meine Mutter angerufen: Papa hatte einen Herzinfarkt, sie waren schon in der Klinik. Ich konnte nicht fahren, meine Hände haben so gezittert.\n\nMarco hat nicht gefragt, sondern die Schlüssel genommen. Er ist dreieinhalb Stunden durchgefahren und hat mir unterwegs immer wieder die Hand aufs Knie gelegt. In der Klinik hat er mit der Ärztin gesprochen, als ich nichts mehr verstanden habe, und mir hinterher alles in Ruhe erklärt. Er hat drei Nächte im Auto auf dem Parkplatz geschlafen, weil bei meiner Mutter kein Platz war, und morgens Brötchen für uns alle geholt. Meine Mutter hat gesagt: „Den behältst du.“\n\nIch schreibe das auf, weil es auch stimmt. In diesen drei Tagen war er genau der Mensch, in den ich mich verliebt habe. Papa geht es inzwischen besser.', 'Unendlich dankbar. Und durcheinander, weil das nicht zu dem anderen passt, das ich hier aufschreibe. Vielleicht übertreibe ich das andere doch.', 4, 'none', '["Zugewandtheit"]'::jsonb, true, 'freetext', '2024-06-01 19:00:00+00', '2024-06-01 19:00:00+00'),
('dec0a000-0000-4000-a000-00000000000a', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 10, 'Zu empfindlich', '2024-07-14', 'Er kneift mir beim Umziehen in den Bauch: „Na, fürs Freibad reicht''s noch nicht.“ Ich sage, dass mich das trifft. „Das war ein Witz. Du bist echt zu empfindlich.“', 'Den Satz höre ich inzwischen jede Woche.', 3, 'none', '["Wahrnehmungsverunsicherung", "Abwertung"]'::jsonb, true, 'freetext', '2024-07-14 19:00:00+00', '2024-07-14 19:00:00+00'),
('dec0a000-0000-4000-a000-00000000000b', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 11, 'Was hast du zu verbergen?', '2024-08-18', E'Als ich aus der Dusche kam, saß Marco auf dem Bett, mein Handy in der Hand. Er hatte meinen Chat mit Jonas gelesen, meinem Kollegen aus dem Leipzig-Projekt. Da stand „Du bist die Beste 🙂“, weil ich für ihn eine Präsentation fertig gemacht hatte, als seine Tochter krank war.\n\nIch habe gesagt, dass er nicht einfach mein Handy lesen kann. Er hat geantwortet: „Wer nichts zu verbergen hat, hat damit auch kein Problem. Was hast du zu verbergen?“ Danach ging es eine Stunde nur noch darum, warum ich so empfindlich reagiere, wenn doch nichts ist.\n\nAm Ende habe ich ihm meinen Code gegeben. Ich wollte, dass Ruhe ist.', 'Überwacht und gleichzeitig die Verdächtige. Seitdem schreibe ich Jonas nur noch das Nötigste.', 4, 'none', '["Schuldumkehr", "Kontrolle", "Anpassung"]'::jsonb, true, 'chat', '2024-08-18 19:00:00+00', '2024-08-18 19:00:00+00'),
('dec0a000-0000-4000-a000-00000000000c', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 12, 'Die Geschichte mit dem Parkhaus', '2024-09-28', E'Tobis Vierzigster, ungefähr dreißig Leute, die meisten kenne ich nur über Marco. Nach dem Essen hat er erzählt, wie ich im Juli an einer Parkhausschranke hängen geblieben bin, weil das Ticket nicht ging, und ihn weinend angerufen habe, während hinter mir alle gehupt haben.\n\nEr hat meine Stimme nachgemacht, hoch und weinerlich: „Marco, die hupen alle!“ Dann hat er vorgeführt, wie ich mich mit beiden Händen ans Lenkrad klammere. Alle haben gelacht. Ich habe mitgelacht, weil alle mich angesehen haben.\n\nWas er nicht erzählt hat: Es war der Tag, an dem mich meine Hausärztin wegen der Schlafprobleme krankschreiben wollte. Es lag nicht am Ticket. Ich konnte einfach nicht mehr.\n\nIm Auto habe ich gesagt, dass mich das verletzt hat. „Alle haben gelacht. Du auch. Jetzt tu nicht so, als wäre das schlimm gewesen.“ Und dann: „Mit dir kann man echt keinen Spaß mehr haben.“', 'Gedemütigt. Und allein damit, weil ich ja mitgelacht habe. Ich habe mich gefragt, ob ich die Einzige war, die es nicht lustig fand.', 4, 'none', '["Wahrnehmungsverunsicherung", "Verachtung"]'::jsonb, true, 'freetext', '2024-09-28 19:00:00+00', '2024-09-28 19:00:00+00'),
('dec0a000-0000-4000-a000-00000000000d', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 13, 'Am Schlüssel hören', '2024-10-20', 'Mir fällt auf, dass ich am Geräusch des Schlüssels in der Tür höre, wie Marcos Laune ist. Danach entscheide ich, was ich koche.', 'Erschrocken, wie normal mir das vorkam.', 3, 'none', '[]'::jsonb, true, 'freetext', '2024-10-20 19:00:00+00', '2024-10-20 19:00:00+00'),
('dec0a000-0000-4000-a000-00000000000e', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 14, 'Paarberatung? Du vielleicht.', '2024-11-10', E'Nach dem Abendessen habe ich ihm den Flyer einer Paarberatungsstelle hingelegt und gesagt, dass ich nicht mehr weiterweiß und uns nicht aufgeben will.\n\nEr hat ihn nicht angefasst. „Mit dir und deinen Problemen müsste man da hin, nicht mit mir.“ Und nach einer Pause: „Geh du ruhig. Dann erzählst du denen wenigstens nicht, dass alles an mir liegt.“', 'Mutlos. Sogar der Versuch, Hilfe zu holen, ist mein Fehler geworden. Den Flyer habe ich am nächsten Tag im Altpapier gefunden.', 3, 'none', '["Schuldumkehr", "Abwertung"]'::jsonb, true, 'guided', '2024-11-10 19:00:00+00', '2024-11-10 19:00:00+00'),
('dec0a000-0000-4000-a000-00000000000f', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 15, 'Ich habe es gesagt', '2025-02-02', E'Mira wollte am Wochenende vorbeikommen, und Marco hat gesagt, dann sei er eben weg, „mit deiner Seelsorgerin setze ich mich nicht an einen Tisch“. Da ist es mir herausgerutscht, so ruhig wie noch nie: „Wenn das so weitergeht, gehe ich.“\n\nIch habe gesehen, wie ihm alles aus dem Gesicht gefallen ist. Er hat angefangen zu weinen, richtig, wie ein Kind. Er hat sich in der Küche auf den Boden gesetzt und gesagt, dass er alles ändert und dass ich das nicht machen darf.\n\nIch muss ehrlich sein: Für einen Moment habe ich mich stark gefühlt. Zum ersten Mal seit Langem hatte ich etwas in der Hand. Danach habe ich mich geschämt. Das war nicht fair, auch wenn ich es ernst meinte.\n\nIch habe den Satz seit dem Sommer schon zweimal gesagt, nur leiser. Ich merke, dass ich ihn benutze.', 'Erleichtert, dass er zuhört, und beschämt, weil er erst zuhört, wenn ich drohe. Ich weiß, dass ich damit auch Druck mache.', 4, 'none', '["Drohung"]'::jsonb, true, 'freetext', '2025-02-02 19:00:00+00', '2025-02-02 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000010', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 16, 'Seit Februar wie ausgewechselt', '2025-05-18', E'Seit dem Abend im Februar ist Marco wie ausgewechselt. Er fragt jeden Abend, wie mein Tag war, und hört sich die Antwort an. Er kocht. Letzten Sonntag hat er Mira zum Essen eingeladen und war den ganzen Abend charmant. Mira hat mir hinterher geschrieben: „Wer ist das, und was hast du mit Marco gemacht?“\n\nFür den Herbst hat er Lissabon vorgeschlagen, nur wir zwei.\n\nIch müsste glücklich sein. Stattdessen warte ich die ganze Zeit darauf, dass es kippt. Wenn er nach Hause kommt, atme ich erst aus, wenn ich seine Stimme gehört habe. Und ich schäme mich, weil ich ihm nicht glauben kann, obwohl er sich so bemüht.', 'Hoffnung und Misstrauen gleichzeitig. Ich komme mir undankbar vor, schon wieder dieses Wort.', 2, 'none', '["Zugewandtheit"]'::jsonb, true, 'guided', '2025-05-18 19:00:00+00', '2025-05-18 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000011', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 17, 'Zurück aus Hamburg', '2025-09-19', E'Drei Tage Hamburg, meine erste Dienstreise als Abteilungsleiterin. Ich war so stolz. Als ich die Tür aufgeschlossen habe, saß er auf dem Sofa und hat nicht aufgesehen: „Na, wie war''s mit deinen wichtigen Leuten?“\n\nDanach zwei Tage kaum ein Wort. Lissabon hat er nicht mehr erwähnt.\n\nDas Seltsame: Ich war fast erleichtert. Da war sie wieder, die alte Stimme, und ich habe gedacht: Siehst du. Ich habe es mir nicht eingebildet.', 'Traurig und seltsam klar. Die guten Monate waren echt, und sie waren trotzdem kein Neuanfang.', 4, 'none', '["Verachtung", "Schweigen/Rückzug"]'::jsonb, true, 'freetext', '2025-09-19 19:00:00+00', '2025-09-19 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000012', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 18, 'Heiligabend vor der Tür', '2025-12-24', E'Wir waren bei seiner Mutter. Gegen neun habe ich Papa angerufen, seit dem Infarkt telefonieren wir an Feiertagen immer lange. Wir haben vielleicht vierzig Minuten gesprochen. Als ich zurück ins Wohnzimmer kam, war die Stimmung eisig.\n\nIm Auto hat er gesagt: „Dann feier doch nächstes Jahr mit deinem Vater.“ Ich habe gesagt, dass das unfair ist. Mehr nicht, ich war nicht laut.\n\nVor unserem Haus hat er angehalten und gesagt, er suche noch einen Parkplatz. Er ist weggefahren. Erst an der Haustür habe ich gemerkt, dass mein Schlüssel an seinem Bund hing. Ich hatte ihn ihm nachmittags gegeben, weil meine Tasche voller Geschenke war.\n\nIch habe ihn angerufen. Elfmal. Eine Nachbarin hat mich ins Treppenhaus gelassen, und ich habe auf der Treppe vor unserer Wohnung gesessen, im Mantel, mit acht Prozent Akku, und durch die Tür den Kater gehört. Die Nachbarin hat gefragt, ob alles in Ordnung ist. Ich habe gesagt, mein Freund sucht nur einen Parkplatz. Später hat sie mir wortlos einen Teller Plätzchen auf die Stufe gestellt.\n\nUm zwanzig vor eins kam er die Treppe hoch, er war bei Tobi. „Du hättest ja bei den Nachbarn klingeln können. Musst du immer so ein Drama machen?“\n\nAm ersten Feiertag hat er Frühstück gemacht, mit Kerzen. Über die Nacht hat er kein Wort verloren. Ich auch nicht.', 'Erschöpft und seltsam klar. Zum ersten Mal eher traurig als schuldig. Auf der Treppe habe ich etwas begriffen, das ich noch nicht aufschreiben kann.', 5, 'none', '["Schuldumkehr", "Schweigen/Rückzug", "Reparatur bleibt aus"]'::jsonb, true, 'freetext', '2025-12-24 19:00:00+00', '2025-12-24 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000013', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 19, 'Katrin alles erzählt', '2026-01-11', E'Ich war übers Wochenende bei meiner Schwester und habe ihr zum ersten Mal alles erzählt. Nicht die Kurzfassung, sondern alles: den Geburtstag, die zwei Wochen, das Handy, Heiligabend.\n\nKatrin hat nichts gesagt, bis ich fertig war. Dann hat sie geweint. Dann hat sie gesagt: „Du entschuldigst dich seit zwei Jahren für Dinge, die er macht. Weißt du das eigentlich?“\n\nIch wusste es nicht. Oder ich wusste es und habe es nicht gehört, solange es nur in meinem Kopf war. Wir haben bis drei Uhr nachts geredet. Sie hat gesagt, ich kann jederzeit bei ihr wohnen.', 'Scham, weil ich so viel verschwiegen habe. Und darunter zum ersten Mal Entlastung: Jemand hat alles gehört und hält mich nicht für verrückt.', 2, 'none', '[]'::jsonb, true, 'guided', '2026-01-11 19:00:00+00', '2026-01-11 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000014', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 20, 'Der Sonntag, an dem ich gegangen bin', '2026-02-22', E'Ich hatte es mit Katrin vorbereitet. Die wichtigsten Sachen waren schon bei ihr, sie hat unten im Auto gewartet. Ich wollte es ruhig sagen, am Tisch, bei Tageslicht, nicht im Streit: „Ich beende unsere Beziehung. Ich ziehe heute zu Katrin.“\n\nIn der nächsten Stunde war er drei verschiedene Menschen. Erst hat er geweint und gefleht: Ich sei der einzige Mensch, der ihn je wirklich gesehen hat, er mache eine Therapie, alles, was ich will. Als ich bei meinem Nein geblieben bin, wurde er laut: „Nach allem, was ich für dich getan habe. Ich habe für deinen Vater drei Nächte im Auto geschlafen.“ Und am Ende ganz ruhig: „Ohne mich schaffst du das nicht. Du hast doch niemanden mehr.“\n\nAls ich meine Jacke genommen habe, hat er sich vor die Wohnungstür gestellt. „Wir reden jetzt zu Ende.“ Vielleicht eine Minute, er hat mich nicht angefasst. Dann hat Katrin angerufen, weil es so lange dauerte, und er ist zur Seite gegangen.\n\nAuf der Treppe musste ich mich am Geländer festhalten. Im Auto hat Katrin nichts gefragt, nur meine Hand gehalten.\n\nBis Mitternacht kamen dreiundzwanzig Nachrichten. Die ersten waren lang und liebevoll. Die letzte: „Du wirst das bereuen.“', 'Zitternd, entschlossen, voller Angst und voller Erleichterung, den ganzen Tag beides gleichzeitig. Die Minute an der Tür träume ich seitdem öfter.', 4, 'elevated', '["Schuldumkehr", "Abwertung", "Übergriffigkeit", "Drohung", "Idealisierung"]'::jsonb, true, 'freetext', '2026-02-22 19:00:00+00', '2026-02-22 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000015', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 21, 'Dienstagabend, 23:14 Uhr', '2026-03-17', E'Dreieinhalb Wochen nach der Trennung kam um 23:14 Uhr eine lange Nachricht. Er habe viel nachgedacht, er habe einen Termin bei einem Therapeuten, er verstehe jetzt, was er mir angetan habe. Ich sei die Liebe seines Lebens, er bitte nur um ein Gespräch.\n\nIch habe bis zwei Uhr Antworten geschrieben und wieder gelöscht.\n\nUm 7:02 Uhr kam die nächste Nachricht: „Die 1.200 Euro für die Küche überweist du bitte bis Freitag. Das ist ja wohl das Mindeste.“', 'Wütend auf mich, weil ich um zwei Uhr fast zurückgeschrieben hätte. Um 7:02 Uhr war ich dann wieder wach.', 3, 'none', '["Idealisierung"]'::jsonb, true, 'chat', '2026-03-17 19:00:00+00', '2026-03-17 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000016', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 22, 'Was die anderen jetzt über mich hören', '2026-04-19', E'Über Tobis Frau habe ich erfahren, was Marco erzählt: dass ich ihn mit einem Kollegen betrogen hätte und gegangen sei, als es ihm schlecht ging. Er nennt Jonas beim Namen.\n\nZwei Paare aus dem gemeinsamen Freundeskreis melden sich seitdem nicht mehr. Eine alte Freundin schreibt, sie wolle sich da raushalten.\n\nIch habe lange Erklärungen an Leute geschrieben, die mich nicht gefragt haben. Abgeschickt habe ich keine.', 'Ohnmächtig gegen ein Bild, das ich nicht geraderücken kann, ohne selbst über ihn herzuziehen.', 4, 'none', '["Isolation"]'::jsonb, true, 'guided', '2026-04-19 19:00:00+00', '2026-04-19 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000017', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 23, 'Drei Anläufe für eine sachliche Mail', '2026-05-13', E'Das gemeinsame Konto ist immer noch nicht aufgelöst. Die Bank braucht beide Unterschriften, und Marco hat seit sechs Wochen jeden Termin verschoben, zweimal eine Stunde vorher.\n\nSeine letzte Mail: „Ich unterschreibe, wenn du endlich zugibst, dass du drei Jahre von meinem Geld gelebt hast.“ Wir waren keine drei Jahre zusammen, und ich habe mehr eingezahlt als er. Das steht in den Auszügen.\n\nFür eine Antwort von vier Sätzen habe ich drei Anläufe gebraucht. Die ersten beiden haben alles erklärt. Katrin hat sie gelesen und gesagt: „Du verteidigst dich schon wieder.“ Die dritte hatte nur noch den Terminvorschlag.', 'Angespannt. Jeder Kontakt zieht mich kurz zurück ins alte Muster. Aber die dritte Mail war meine.', 3, 'none', '["Kontrolle", "Drohung"]'::jsonb, true, 'guided', '2026-05-13 19:00:00+00', '2026-05-13 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000018', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 24, 'Ein Samstag mit Mira', '2026-06-06', E'Mit Mira auf dem Flohmarkt am Kanal, zum ersten Mal seit über einem Jahr einfach so, ohne vorher zu überlegen, was ich zu Hause sage. Wir haben über eine hässliche Vase so gelacht, dass die Leute geguckt haben.\n\nIch habe ihr gesagt, dass es mir leidtut, das mit meinem Geburtstag, dass ich gar nicht krank war. Sie hat gesagt: „Das weiß ich doch längst.“\n\nAbends ist mir aufgefallen, dass ich den ganzen Tag nicht aufs Handy geschaut habe.', 'Leicht. So kann es sich also anfühlen.', 1, 'none', '[]'::jsonb, true, 'freetext', '2026-06-06 19:00:00+00', '2026-06-06 19:00:00+00'),
('dec0a000-0000-4000-a000-000000000019', 'dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 25, 'Eine Nachricht wegen der Winterjacke', '2026-07-02', E'Eine einzige Nachricht von Marco, ohne Gruß: „Deine Winterjacke hängt noch hier. Hol sie bis Sonntag, sonst kommt sie weg.“\n\nDas hat für zwei Tage gereicht. Ich habe schlecht geschlafen, bei der Arbeit dreimal denselben Absatz gelesen und mich gefragt, ob ich nicht doch die ganze Zeit überempfindlich war. Ob ich das Problem war.\n\nAm zweiten Abend habe ich Katrin angerufen. Wir haben zehn Minuten geredet, fast nur über anderes. Danach habe ich geantwortet: „Ich hole sie Samstag um elf. Leg sie bitte in den Flur.“ Ein Satz, ohne Erklärung.', 'Frustriert, dass eine Nachricht noch so viel Macht hat. Und ein bisschen stolz auf den einen Satz.', 3, 'none', '[]'::jsonb, true, 'freetext', '2026-07-02 19:00:00+00', '2026-07-02 19:00:00+00');
INSERT INTO scenes (id, case_id, user_id, scene_no, title, scene_date, description, user_reaction, distress_score, safety_level, pattern_tags, confirmed_by_user, input_mode, created_at, updated_at) VALUES
('dec0b000-0000-4000-a000-000000000001', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 1, 'Endlich jemand, der bleibt', '2023-09-16', E'Ich habe Lena Ende August auf dem Geburtstag ihrer besten Freundin kennengelernt. Eigentlich wollte ich nach einer Stunde gehen, und dann war es drei Uhr morgens.\n\nIch schreibe ihr jeden Morgen, bevor sie aufwacht. Ich will, dass das Erste, was sie am Tag sieht, von mir ist. Nach drei Wochen habe ich ihr gesagt, dass ich so etwas noch nie erlebt habe, und das stimmt.\n\nMein Vater ist gegangen, als ich elf war. Er hat es zweimal angekündigt, beim dritten Mal war er weg, und meine Mutter hat ein Jahr lang abends in der Küche geweint. Seitdem war ich in jeder Beziehung der, der auf den Moment wartet, in dem die andere geht.\n\nMit Lena ist das zum ersten Mal anders. Ich will keine Zeit verlieren.', 'Glücklich. Zum ersten Mal seit Jahren nicht auf der Hut.', 1, 'none', '["Idealisierung"]'::jsonb, true, 'freetext', '2023-09-16 19:00:00+00', '2023-09-16 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000002', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 2, 'Das Abendessen mit ihrem Team', '2023-11-04', E'Essen mit Lenas Kollegen. Sie hat von ihrem Projekt in Leipzig erzählt und dabei Sachen durcheinandergebracht, eine Zahl war falsch. Ich habe es freundlich korrigiert, damit es keiner merkt.\n\nIm Auto habe ich gesagt, dass das ein bisschen peinlich war. Vielleicht zu direkt, das gebe ich zu. Aber ich will nicht, dass Leute über sie lachen, und ich bin nun mal ehrlich. Sie hat sich sofort entschuldigt und war den ganzen Abend beleidigt.', 'Genervt. Wenn ich etwas Ehrliches sage, ist es gleich ein Angriff.', 2, 'none', '["Abwertung", "Rechtfertigung/Abwehr"]'::jsonb, true, 'guided', '2023-11-04 19:00:00+00', '2023-11-04 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000003', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 3, 'Mira', '2024-01-18', E'Mira hat uns zusammengebracht, und seit wir zusammen sind, arbeitet sie daran, uns auseinanderzubringen. So kommt es mir jedenfalls vor.\n\nJedes Mal, wenn Lena von ihr kommt, ist sie anders. Stiller, und sie stellt Fragen, die nicht von ihr sind: ob ich nicht ein bisschen viel wissen will, wo sie ist.\n\nIch habe Lena gesagt, dass Mira sie runterzieht. Das ist meine Meinung, die darf ich sagen. Ich habe nie gesagt, dass sie sie nicht treffen soll.\n\nHeute war sie angeblich länger im Büro. Ihr Mantel roch nach Popcorn.', 'Ausgeschlossen. Und eifersüchtig auf eine Freundschaft, was ich mir nicht gern eingestehe.', 3, 'none', '["Isolation", "Rechtfertigung/Abwehr"]'::jsonb, true, 'freetext', '2024-01-18 19:00:00+00', '2024-01-18 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000004', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 4, 'Der Mantel', '2024-03-02', 'Ich habe gefragt, wofür sie den Mantel braucht. Eine Frage. Für Lena war das gleich ein Verhör. Einer von uns muss aufs Geld achten, und sie kauft, wenn es ihr schlecht geht. Das Rennrad war etwas anderes, das brauche ich für meinen Rücken, das weiß sie.', 'Missverstanden. Aus Vernunft wird bei ihr Kontrolle.', 2, 'none', '["Kontrolle", "Rechtfertigung/Abwehr"]'::jsonb, true, 'guided', '2024-03-02 19:00:00+00', '2024-03-02 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000005', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 5, 'Ihr Geburtstag', '2024-04-12', E'Ich hatte seit Januar geplant. Ein Wellnesshotel an der Seenplatte, das Zimmer mit Blick aufs Wasser, 480 Euro, weil ich wollte, dass sie an ihrem Geburtstag einmal nur gefeiert wird und nicht selbst alles organisiert.\n\nBeim Frühstück habe ich ihr den Umschlag gegeben. Sie hat sich kurz gefreut und dann gefragt, ob wir nicht morgen fahren können, heute sei doch der Italiener mit ihren Leuten. Das hatte ich ehrlich gesagt verdrängt. In dem Moment kam ich mir vor wie eine Option unter mehreren.\n\nIch habe in die Gruppe geschrieben, dass sie krank ist und wir absagen. Ich dachte, wenn der Abend frei ist, sieht sie, wie ernst ich es meine. Das war falsch, das weiß ich heute. Damals kam es mir wie eine Kleinigkeit vor, ihre Freundinnen sieht sie ja ständig.\n\nAls sie es gemerkt hat, hat sie mich angesehen, als hätte ich ihr etwas gestohlen. Ich habe gesagt, dass sie undankbar ist. Ich war so enttäuscht, dass ich geweint habe.\n\nIm Hotel war es dann schön. Finde ich. Wir haben gut gegessen, und ich habe ihr gesagt, wie viel sie mir bedeutet. Sie sagt heute, sie sei den ganzen Abend nicht da gewesen. Gemerkt habe ich davon nichts.', 'Enttäuscht, dass meine Mühe nichts gezählt hat. Im Nachhinein beschämt über die Nachricht in der Gruppe.', 3, 'none', '["Isolation", "Rechtfertigung/Abwehr"]'::jsonb, true, 'freetext', '2024-04-12 19:00:00+00', '2024-04-12 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000006', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 6, 'Ich konnte nicht reden', '2024-04-16', E'Am Sonntag nach dem Geburtstag hat Lena wieder damit angefangen, dass ich ihre Freundinnen belogen habe. Da ging bei mir etwas zu. Ich habe tagelang kaum gesprochen.\n\nMein Vater hat geschrien, wenn er wütend war, und hinterher Sachen gesagt, die man nicht zurücknehmen kann. Ich habe mir als Junge geschworen, dass ich nie so werde. Lieber still.\n\nLena sagt, es waren zwei Wochen und ich hätte sie bestraft. Für mich waren es ein paar schlechte Tage, in denen ich Ruhe gebraucht habe. Ich habe mit dem Kater geredet, weil der wenigstens nichts von mir wollte.\n\nIrgendwann hat sie sich entschuldigt, und dann ging es wieder.', 'Erschöpft und sprachlos. Ich wusste nicht, wie ich zurückkommen soll, ohne zuzugeben, dass die Nachricht in der Gruppe falsch war.', 4, 'none', '["Schweigen/Rückzug"]'::jsonb, true, 'chat', '2024-04-16 19:00:00+00', '2024-04-16 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000007', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 7, 'Die drei Tage im Krankenhaus', '2024-06-01', E'Lenas Vater hatte einen Herzinfarkt. Ich bin nachts mit ihr hingefahren, dreieinhalb Stunden, sie hat die ganze Fahrt gezittert.\n\nIn der Klinik wusste ich endlich einmal genau, was zu tun ist. Mit der Ärztin reden, Kaffee holen, ihre Mutter beruhigen. Ich habe drei Nächte im Auto geschlafen, und es hat mir nichts ausgemacht. Im Wartebereich ist Lena an meiner Schulter eingeschlafen, und ich habe mich zwei Stunden lang nicht bewegt.\n\nEs klingt vielleicht komisch, aber das waren unsere besten Tage. Sie hat mich gebraucht, und ich war gut in dem, was ich getan habe.', 'Nah bei ihr. Ruhig. So habe ich mir uns immer vorgestellt.', 3, 'none', '["Zugewandtheit"]'::jsonb, true, 'freetext', '2024-06-01 19:00:00+00', '2024-06-01 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000008', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 8, 'Das Handy', '2024-08-18', E'Sie war unter der Dusche, ihr Handy lag auf dem Bett und hat vibriert. Jonas. Ich hatte seit Wochen so ein Gefühl, weil sie abends oft lächelnd aufs Handy geschaut hat.\n\nIch habe den Chat gelesen. Da stand „Du bist die Beste 🙂“. Heute weiß ich, dass das nichts war, eine Arbeitssache. In dem Moment war es für mich ein Beweis.\n\nIch habe gefragt, was sie zu verbergen hat. Das fand ich damals eine berechtigte Frage. Sie wollte nur darüber reden, dass ich ihr Handy genommen habe, und nicht darüber, warum ich so unsicher war.\n\nAm Ende hat sie mir ihren Code gegeben. Ich dachte, dann ist Ruhe in meinem Kopf. Es war keine Ruhe. Ich habe danach noch ein paar Mal nachgesehen. Nicht oft.', 'Beschämt über mich und gleichzeitig allein mit meiner Unsicherheit.', 4, 'none', '["Schuldumkehr", "Kontrolle"]'::jsonb, true, 'freetext', '2024-08-18 19:00:00+00', '2024-08-18 19:00:00+00'),
('dec0b000-0000-4000-a000-000000000009', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 9, 'Tobis Vierzigster', '2024-09-28', 'Die Parkhaus-Geschichte erzählt, alle haben gelacht, Lena auch. Im Auto dann wieder Drama. Man darf bei ihr überhaupt nichts mehr sagen.', 'Genervt.', 2, 'none', '["Rechtfertigung/Abwehr"]'::jsonb, true, 'freetext', '2024-09-28 19:00:00+00', '2024-09-28 19:00:00+00'),
('dec0b000-0000-4000-a000-00000000000a', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 10, 'Sie hat es gesagt', '2025-02-02', E'Es ging wieder um Mira, die am Wochenende kommen wollte. Ich habe gesagt, dann bin ich eben weg, und einen blöden Spruch gemacht. Dann hat Lena gesagt: „Wenn das so weitergeht, gehe ich.“\n\nIch weiß nicht, wie ich beschreiben soll, was da passiert ist. Es war, als wäre der Boden weg. Mein Vater hat genau so angefangen. Zweimal angekündigt, beim dritten Mal war er weg.\n\nIch habe geweint und sie angefleht, auf dem Küchenboden. Ich habe versprochen, dass ich mich ändere, und ich habe es ernst gemeint.\n\nSie hat den Satz vorher schon gesagt, im Sommer und im Herbst, aber nie so ruhig. Diesmal habe ich ihr geglaubt.\n\nSeitdem gebe ich mir Mühe wie nie. Ich frage, wie ihr Tag war. Ich koche. Ich lade Mira ein. Und jeden Abend, wenn ich nach Hause komme, schaue ich als Erstes in den Flur, ob ihre Tasche noch da steht.', 'Panik. Danach Wochen, in denen ich funktioniert habe wie einer, der eine Prüfung schreibt.', 5, 'none', '["Drohung", "Anpassung"]'::jsonb, true, 'freetext', '2025-02-02 19:00:00+00', '2025-02-02 19:00:00+00'),
('dec0b000-0000-4000-a000-00000000000b', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 11, 'Hamburg', '2025-09-19', E'Drei Tage Hamburg, und sie kommt zurück, als wäre sie jemand anderes. Abteilungsleiterin. Ich habe gefragt, wie es mit ihren wichtigen Leuten war. Ein Witz. Sie hat wieder dieses Gesicht gemacht.\n\nIch hatte keine Kraft mehr, so zu tun, als wäre alles gut. Monatelang habe ich mich zusammengerissen, und sie fährt weg und ist glücklich ohne mich.', 'Leer. Und wütend, ohne zu wissen, auf wen.', 3, 'none', '["Schweigen/Rückzug"]'::jsonb, true, 'freetext', '2025-09-19 19:00:00+00', '2025-09-19 19:00:00+00'),
('dec0b000-0000-4000-a000-00000000000c', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 12, 'Heiligabend', '2025-12-24', E'Heiligabend bei meiner Mutter. Lena war fast eine Stunde mit ihrem Vater am Telefon, im Flur, während meine Mutter mit dem Essen gewartet hat. Meine Mutter hat nichts gesagt, aber ich habe gesehen, wie sie geguckt hat.\n\nIm Auto habe ich etwas Falsches über ihren Vater gesagt. Sie hat gesagt, das sei unfair. Ich habe gemerkt, dass ich gleich laut werde, und das wollte ich nicht, nicht an Weihnachten. Also habe ich sie vor dem Haus rausgelassen und bin zu Tobi gefahren. Ich musste raus.\n\nDass ihr Schlüssel an meinem Bund hing, habe ich nicht gewusst. Sie hat ihn mir nachmittags zwischen zwei Geschenktüten in die Hand gedrückt. Mein Handy war auf lautlos.\n\nAls ich um halb eins kam, saß sie auf der Treppe. Elf verpasste Anrufe. Ich habe gesagt, sie hätte ja bei den Nachbarn klingeln können. Ich weiß, wie das klingt.\n\nAm Morgen habe ich Frühstück gemacht, mit Kerzen. Ich dachte, das sagt mehr als eine Entschuldigung.', 'Schuldig und gleichzeitig trotzig. Ich wollte nicht schon wieder der sein, der alles falsch gemacht hat.', 4, 'none', '["Schuldumkehr", "Schweigen/Rückzug", "Reparatur bleibt aus"]'::jsonb, true, 'freetext', '2025-12-24 19:00:00+00', '2025-12-24 19:00:00+00'),
('dec0b000-0000-4000-a000-00000000000d', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 13, 'Ihre Schwester wartete unten im Auto', '2026-02-22', E'Sie hat es am Küchentisch gesagt, ganz ruhig, als würde sie einen Termin absagen. Ihre Sachen waren schon weg, das habe ich erst danach gesehen. Ihre Schwester hat unten im Auto gewartet.\n\nDas hat mir fast am meisten wehgetan. Sie hatte das geplant, mit ihrer Familie, wochenlang, während sie neben mir geschlafen hat.\n\nIch habe gebettelt, ja. Ich habe ihr gesagt, dass sie der einzige Mensch ist, der mich je wirklich gesehen hat. Als sie bei ihrem Nein blieb, habe ich Dinge gesagt, die ich nicht sagen wollte. Dass ich für ihren Vater drei Nächte im Auto geschlafen habe. Dass sie ohne mich nichts auf die Reihe kriegt.\n\nAn dem Abend habe ich ihr viele Nachrichten geschrieben. Was in allen stand, weiß ich nicht mehr genau.', 'Fassungslos und verlassen. Stundenlang abwechselnd flehend und wütend.', 5, 'none', '["Schuldumkehr", "Abwertung", "Idealisierung"]'::jsonb, true, 'freetext', '2026-02-22 19:00:00+00', '2026-02-22 19:00:00+00'),
('dec0b000-0000-4000-a000-00000000000e', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 14, 'Was sie erzählt und was ich erzähle', '2026-04-19', E'Über Bekannte höre ich, dass Lena überall erzählt, ich sei kontrollierend und kalt gewesen. Ich erkenne mich darin nicht.\n\nAlso habe ich Tobi und ein paar anderen erzählt, wie es wirklich war. Dass es da diesen Kollegen gab, mit dem sie ständig geschrieben hat. Das ist ja nicht gelogen. Es gab ihn.\n\nDass ich nie etwas gefunden habe, habe ich nicht dazugesagt. Aufgefallen ist mir das erst, als Tobis Frau gefragt hat, ob ich mir sicher bin.', 'Ohnmächtig gegen eine Geschichte, die mich zum Täter macht. Und seit der Frage von Tobis Frau nicht mehr sicher, ob meine besser ist.', 3, 'none', '["Isolation", "Rechtfertigung/Abwehr"]'::jsonb, true, 'guided', '2026-04-19 19:00:00+00', '2026-04-19 19:00:00+00'),
('dec0b000-0000-4000-a000-00000000000f', 'dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 15, 'Was ich eigentlich gesucht habe', '2026-08-04', E'Seit Juni gehe ich alle zwei Wochen zu einer Männerberatung. Hingegangen bin ich, um zu verstehen, was Lena falsch gemacht hat. Das habe ich dem Berater in der ersten Stunde auch so gesagt.\n\nHeute hat er nach dem Handy gefragt. Was ich gesucht habe, als ich ihre Nachrichten gelesen habe.\n\nIch habe gesagt: Beweise. Er hat gefragt: Wofür? Ich wollte sagen: dass sie mich betrügt. Herausgekommen ist: dass sie geht.\n\nDann hat er gefragt, was gewesen wäre, wenn ich nie etwas gefunden hätte. Ich habe nie etwas gefunden. Und ich habe trotzdem weitergesucht, im Handy, bei Mira, in ihrem Gesicht, als sie aus Hamburg kam.\n\nAuf dem Heimweg ist mir mein Vater eingefallen. Nicht der, der geschrien hat, sondern der Junge, der ich war und jeden Abend nachgesehen hat, ob sein Auto noch vor der Tür steht.\n\nIch will nicht, dass jetzt alles meine Schuld ist. Aber ich will auch nicht, dass die Nächste irgendwann ihre Tasche packt und ich wieder nicht verstehe, warum.', 'Aufgewühlt. Zum ersten Mal traurig statt wütend.', 3, 'none', '[]'::jsonb, true, 'freetext', '2026-08-04 19:00:00+00', '2026-08-04 19:00:00+00');
INSERT INTO scale_scores (case_id, user_id, scale_key, score, scene_count, confidence, source_scene_ids, notes) VALUES
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'guilt_shifting', 84, 6, 'high', '["dec0a000-0000-4000-a000-000000000006", "dec0a000-0000-4000-a000-00000000000b", "dec0a000-0000-4000-a000-00000000000e", "dec0a000-0000-4000-a000-000000000012", "dec0a000-0000-4000-a000-000000000013", "dec0a000-0000-4000-a000-000000000014"]'::jsonb, 'Konflikte kippen regelhaft in einen Vorwurf an Lena; sie entschuldigt sich am Ende selbst (Szenen 6, 19).'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'perception_distortion', 78, 4, 'high', '["dec0a000-0000-4000-a000-000000000003", "dec0a000-0000-4000-a000-00000000000a", "dec0a000-0000-4000-a000-00000000000b", "dec0a000-0000-4000-a000-00000000000c"]'::jsonb, 'Erinnerung und Empfinden werden wiederholt für falsch erklärt; Lena sucht Belege, um sich selbst zu glauben (Szene 3).'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'control_isolation', 74, 6, 'high', '["dec0a000-0000-4000-a000-000000000004", "dec0a000-0000-4000-a000-000000000005", "dec0a000-0000-4000-a000-000000000006", "dec0a000-0000-4000-a000-00000000000b", "dec0a000-0000-4000-a000-000000000016", "dec0a000-0000-4000-a000-000000000017"]'::jsonb, 'Kontrolle über Konto und Handy, Absage des Geburtstags über ihren Kopf hinweg; nach der Trennung Rückzug gemeinsamer Freunde.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'proximity_distance', 72, 6, 'medium', '["dec0a000-0000-4000-a000-000000000001", "dec0a000-0000-4000-a000-000000000007", "dec0a000-0000-4000-a000-000000000008", "dec0a000-0000-4000-a000-000000000010", "dec0a000-0000-4000-a000-000000000011", "dec0a000-0000-4000-a000-000000000015"]'::jsonb, 'Wechsel aus überschießender Zuwendung und wochenlangem Schweigen, zuletzt als Nachricht um 23:14 und 7:02 Uhr.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'boundary_violation', 70, 6, 'medium', '["dec0a000-0000-4000-a000-000000000005", "dec0a000-0000-4000-a000-000000000006", "dec0a000-0000-4000-a000-00000000000a", "dec0a000-0000-4000-a000-00000000000b", "dec0a000-0000-4000-a000-00000000000c", "dec0a000-0000-4000-a000-000000000014"]'::jsonb, 'Handy gelesen, Code eingefordert, Spott vor Dritten, beim Auszug die Tür versperrt. Keine Berührung, keine Gewalt geschildert.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'conflict_escalation', 38, 2, 'low', '["dec0a000-0000-4000-a000-000000000012", "dec0a000-0000-4000-a000-000000000014"]'::jsonb, 'Wenig offene Eskalation: Konflikte enden eher im Schweigen als im Streit.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'safety_risk', 36, 2, 'medium', '["dec0a000-0000-4000-a000-000000000014", "dec0a000-0000-4000-a000-000000000017"]'::jsonb, 'Keine körperliche Gewalt. Beim Auszug eine Minute der Weg versperrt, danach eine Drohung und Druck über das Konto. Im Erstgespräch ansprechen.');
INSERT INTO topic_summaries (case_id, user_id, topic, summary_text) VALUES
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'topic_self', 'Lena beschreibt sich als leistungsfähig, empathisch und lange sehr nachgiebig. Sie hat gelernt, ihrer Wahrnehmung zu misstrauen, und beobachtet an sich Wachsamkeit („am Schlüssel hören“) und Schlafprobleme. Seit der Trennung kehren Ressourcen zurück: die Schwester, die beste Freundin, kurze klare Antworten.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'topic_person', 'Marco erscheint in ihren Szenen charmant, fürsorglich in der Krise und zugleich abwertend, kontrollierend und schnell gekränkt, vor allem wenn Lena eigene Wege geht. Auffällig sind Schuldumkehr, Schweigen als Reaktion auf Kritik und große Gesten, die ein Gespräch ersetzen.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'topic_responsibility', 'Lena benennt eigene Anteile: dass sie sich vorschnell entschuldigt, Treffen verschwiegen und mehrfach mit Trennung gedroht hat. Die Aufgabe ist, diese Anteile ernst zu nehmen, ohne sie gegen Marcos Verhalten aufzurechnen.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'topic_guilt', 'Schuldgefühle tauchen vor allem nach Kontakt mit Marco auf und wirken eher durch Druck erzeugt als durch eigenes Fehlverhalten begründet. Wiederkehrendes Wort: „undankbar“.');
INSERT INTO case_hypotheses (case_id, user_id, hypothesis_type, summary_text) VALUES
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'hyp_dynamics', 'Wiederkehrender Ablauf: Lena bewegt sich eigenständig (Freundin, Geburtstag, Beförderung) → Spitze oder Schweigen → Lena entschuldigt sich → große Geste ohne Klärung. Nach ihrer Trennungsdrohung eine monatelange Phase echter Zuwendung, die beim nächsten Autonomieschritt endet (Szenen 15–17).'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'hyp_clusterb', 'Im Fremdbericht mehrere narzisstisch anmutende Anhaltspunkte bei Marco (Kränkbarkeit bei Eigenständigkeit, Herabsetzung vor Dritten, Schuldumkehr). Deutliche Gegenbelege: verlässliche Fürsorge in der Krise (Szene 9), monatelange Zuwendung (Szene 16). Einseitige Quelle, ausdrücklich keine Diagnose.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'hyp_attachment', 'Bei Lena Hinweise auf ängstliche Bindungsanteile: Schweigephasen lösen Verzweiflung und Einlenken aus (Szene 7), gute Phasen werden misstrauisch überwacht (Szene 16). Das verstärkt den Sog des Nähe-Distanz-Wechsels.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'hyp_trauma', 'Zeichen kumulativer Belastung: Hypervigilanz (Szene 13), Schlafstörung (Szenen 7, 12), Grübeln nach kleinsten Kontakten (Szene 25). Stabilisierung und Psychoedukation vor jeder Konfrontation.'),
('dec01000-0000-4000-a000-0000000000ca', 'dec01000-0000-4000-a000-000000000001', 'hyp_own_role', 'Lenas Anteil liegt in früh übergangenen eigenen Grenzen, vorauseilender Anpassung und der Trennungsdrohung als Hebel (Szene 15). Als verständliche Schutzstrategien zu würdigen, nicht als Schuld.');
INSERT INTO scale_scores (case_id, user_id, scale_key, score, scene_count, confidence, source_scene_ids, notes) VALUES
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'proximity_distance', 68, 5, 'medium', '["dec0b000-0000-4000-a000-000000000001", "dec0b000-0000-4000-a000-000000000007", "dec0b000-0000-4000-a000-00000000000a", "dec0b000-0000-4000-a000-00000000000b", "dec0b000-0000-4000-a000-00000000000d"]'::jsonb, 'Erlebt Lenas Trennungsankündigungen und eigene Wege als drohenden Verlust; reagiert mit Klammern oder Rückzug.'),
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'guilt_shifting', 54, 4, 'medium', '["dec0b000-0000-4000-a000-000000000002", "dec0b000-0000-4000-a000-000000000005", "dec0b000-0000-4000-a000-000000000008", "dec0b000-0000-4000-a000-00000000000c"]'::jsonb, 'Fühlt sich regelhaft als der Schuldige; eigene Vorwürfe an Lena stehen in denselben Szenen.'),
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'perception_distortion', 36, 2, 'low', '["dec0b000-0000-4000-a000-000000000006", "dec0b000-0000-4000-a000-00000000000e"]'::jsonb, 'Erlebt seine Absichten (Sorge, Planung, Ruhe) als umgedeutet, beginnt aber selbst zu zweifeln (Szene 14).'),
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'conflict_escalation', 34, 2, 'low', '["dec0b000-0000-4000-a000-00000000000a", "dec0b000-0000-4000-a000-00000000000d"]'::jsonb, 'Offene Eskalation selten; Konflikte enden eher in Rückzug.');
INSERT INTO topic_summaries (case_id, user_id, topic, summary_text) VALUES
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'topic_self', 'Marco beschreibt sich als loyal, bemüht und mit großer Angst, verlassen zu werden, die er auf den Weggang des Vaters zurückführt. Eigenen Rückzug erlebt er als Schutz davor, laut zu werden. In der Beratung beginnt er, Kontrolle als Suche nach Sicherheit zu verstehen (Szene 15).'),
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'topic_person', 'Lena erscheint ihm als zunehmend kritisch, von ihrer Freundin beeinflusst und mit einem Leben, in dem er nur eine Option unter mehreren ist. Ihre Trennungsankündigungen erlebt er als Bedrohung, ihre Selbstständigkeit als Abwendung.'),
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'topic_responsibility', 'Marco benennt einzelne Fehler ausdrücklich (die Nachricht in der Gruppe, das Handy), relativiert sie aber meist im selben Atemzug. Wie sein Schweigen und seine Spitzen auf Lena gewirkt haben, kommt kaum vor.');
INSERT INTO case_hypotheses (case_id, user_id, hypothesis_type, summary_text) VALUES
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'hyp_attachment', 'Bei Marco Hinweise auf ängstlich-ambivalente Bindungsanteile mit ausgeprägter Verlustangst (Weggang des Vaters, Szenen 1 und 10): Autonomieschritte der Partnerin lösen Kontrolle oder Rückzug aus, Trennungsankündigungen Panik und Klammern. Tastend, keine Diagnose.'),
('dec01000-0000-4000-a000-0000000000cb', 'dec01000-0000-4000-a000-000000000002', 'hyp_own_role', 'Marcos Eigenanteil liegt in Kontrollhandlungen, die er als Sorge erlebt (Handy, Konto, Absage des Geburtstags), und in Rückzug, dessen Wirkung auf die Partnerin er nicht sieht. Erste eigene Einsicht in Szene 15; mit dem Ziel zu würdigen, Verantwortung ohne Selbstverurteilung zu übernehmen.');
